///|
fn parse(toml_text : String) -> Json raise ParseError {
  let result = Map::new()
  let mut current_prefix : String = ""
  let lines = toml_text.split("\n").to_array()
  let mut line_no = 0
  while line_no < lines.length() {
    let raw_line = lines[line_no]
    line_no = line_no + 1
    let line = raw_line.trim().to_owned()

    // Skip blank and comment lines
    if line.is_empty() || line[0] == 0x23 {
      continue
    }

    // Table header [key] or [key.subkey]
    if line[0] == 0x5B {
      if line[line.length() - 1] != 0x5D {
        raise InvalidSyntax("Unclosed table header: " + raw_line.trim().to_owned())
      }
      let inner = line.sub(start=1, end=line.length() - 1).trim().to_owned()
      current_prefix = parse_dotted_key(inner)
      continue
    }

    // key = value
    let eq_pos = find_first_eq(line)
    if eq_pos == -1 {
      raise InvalidSyntax("Missing '=' in key-value pair: " + raw_line.trim().to_owned())
    }
    let key_part = line.sub(start=0, end=eq_pos).trim().to_owned()
    let value_part = line.sub(start=eq_pos + 1, end=line.length()).trim().to_owned()

    let key_path = parse_dotted_key_for_values(key_part)
    let full_key = if current_prefix.is_empty() {
      key_path
    } else {
      current_prefix + "." + key_path
    }
    let value = parse_value(value_part)

    if result.contains(full_key) {
      raise DuplicateKey(full_key, "Duplicate key: " + full_key)
    }
    result[full_key] = value
  }

  flat_map_to_nested_json(result)
}

///|
fn find_first_eq(s : String) -> Int {
  for i = 0; i < s.length(); i = i + 1 {
    if s[i] == 0x3D {
      return i
    }
  }
  -1
}

///|
fn parse_dotted_key(key : String) -> String raise ParseError {
  let parts = key.split(".").to_array()
  let result = StringBuilder::new()
  for i = 0; i < parts.length(); i = i + 1 {
    let part = parts[i].trim().to_owned()
    if part.is_empty() {
      raise InvalidSyntax("Empty key part in: " + key)
    }
    validate_bare_key(part)
    if i > 0 {
      result.write_string(".")
    }
    result.write_string(part)
  }
